llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Asciminib, a close-transfer oral drug with heteroaromatic and polar substituents, has an absolute oral bioavailability of approximately 73% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Ofloxacin, a fluoroquinolone containing a carboxylic acid and piperazine, is essentially completely absorbed orally with F ≈ 100% in human volunteers, showing that ionizable polar acids can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Levofloxacin, structurally related to ofloxacin, has an absolute oral bioavailability of 99% after a 500 mg oral dose in healthy volunteers, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pradigastat, a lipophilic carboxylic acid with slow absorption, has a moderate absolute oral bioavailability of about 40% in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "LY2196044, an oral immediate-release capsule drug with amide and ether functionality, has an estimated human bioavailability of 45%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Zidovudine, a polar nucleoside analogue, has an absolute oral bioavailability of about 63% in humans, demonstrating that polar drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Compound 109, a heteroaryl drug with a piperidine lactam, has a predicted human oral bioavailability of approximately 70%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Doxifluridine, a nucleoside analogue, shows human oral bioavailability values of 34–47%, all above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability: multiple structurally related polar and ionizable drugs have human F values of 34–100%, all above the 20% threshold. The query's phosphate group is a potential permeability liability, but no affirmative low-F evidence exists, and the closest analogues with acidic or polar groups are well absorbed.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule or a close phosphate-containing analogue.",
    "The phosphate monoester group in the query may reduce membrane permeability and oral absorption more than the carboxylic acids present in the evidence molecules.",
    "One zidovudine record (C25) reports an implausible F value of 2.28 ± 0.9, inconsistent with all other zidovudine data and likely a unit or typographical error; it was not used as low-bioavailability evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

